/bin/zsh -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
*, *::before, *::after {
  box-sizing: border-box;
}
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at center, #161922 0%, #090a0f 100%);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-user-select: none;
  user-select: none;
}
#stage {
  display: block;
  width: 100vw;
  height: 100vh;
}

#countdown {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 50;
  pointer-events: none;
  font-size: 96px;
  font-weight: 700;
  line-height: 1;
  color: rgba(255, 255, 255, 0.35);
  font-variant-numeric: tabular-nums;
}

#dock {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  width: 536px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 14px;
  background: rgba(15, 17, 23, 0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
}

#dock button {
  font-family: inherit;
  line-height: 1;
  margin: 0;
  flex-shrink: 0;
  white-space: nowrap;
  appearance: none;
  -webkit-appearance: none;
}

.dock-sep {
  width: 1px;
  height: 18px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.12);
}

#btn-refire {
  width: 78px;
  height: 28px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
#btn-refire:hover {
  background: rgba(255, 255, 255, 0.16);
}

#btn-toggle {
  width: 28px;
  height: 28px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  cursor: pointer;
}
#btn-toggle:hover {
  background: rgba(255, 255, 255, 0.16);
}

#speed-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.speed-pill {
  width: 42px;
  height: 24px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 9999px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
.speed-pill:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
}
.speed-pill.is-active {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.2);
}

#scrubber {
  width: 157px;
  height: 4px;
  margin: 0;
  padding: 0;
  flex-shrink: 0;
  appearance: none;
  -webkit-appearance: none;
  background: rgba(255, 255, 255, 0.22);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
}
#scrubber::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}
#scrubber::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}
</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
window.addEventListener('"'DOMContentLoaded', function () {
  'use strict';

  const DURATION = 8;
  const COUNTDOWN = 'COUNTDOWN';
  const PLAYING = 'PLAYING';
  const PAUSED = 'PAUSED';
  const REFIRE_HOLD = 'REFIRE_HOLD';
  const ENDED = 'ENDED';
  const PHYSICAL_DROP_LENGTH_M = 0.12;
  const FRACTURE_SPEED_M_S = 1600;
  const FRACTURE_REAL_SECONDS = PHYSICAL_DROP_LENGTH_M / FRACTURE_SPEED_M_S;
  const FRACTURE_SCREEN_SECONDS = 1.4;

  const canvas = document.getElementById('stage');
  const countdown = document.getElementById('countdown');
  const scrubber = document.getElementById('scrubber');
  const toggle = document.getElementById('btn-toggle');
  const refire = document.getElementById('btn-refire');
  const iconPause = document.getElementById('icon-pause');
  const iconPlay = document.getElementById('icon-play');
  const speedPills = Array.from(document.querySelectorAll('.speed-pill'));
  countdown.style.display = 'none';
  countdown.textContent = '';

  // All random choices are made once, from the same fixed seed.
  function mulberry32(seed) {
    return function () {
      let n = seed += 0x6D2B79F5;
      n = Math.imul(n "'^ n >>> 15, n | 1);
      n ''^= n + Math.imul(n ''^ n >>> 7, n | 61);
      return ((n ''^ n >>> 14) >>> 0) / 4294967296;
    };
  }
  const random = mulberry32(42);
  const rand = (a, b) => a + (b - a) * random();
  const clamp = THREE.MathUtils.clamp;
  const smooth = (a, b, v) => {
    const x = clamp((v - a) / (b - a), 0, 1);
    return x * x * (3 - 2 * x);
  };

  const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('"'stage'), antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.2;
  renderer.setClearColor(0x000000, 0);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 100);
  function resize() {
    const aspect = window.innerWidth / window.innerHeight;
    const visibleHeight = Math.max(8.0, 7.2 / aspect);
    camera.aspect = aspect;
    camera.position.set(0.35, 0.16, visibleHeight / (2 * Math.tan(THREE.MathUtils.degToRad(35 / 2))));
    camera.lookAt(0.35, 0.16, 0);
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(window.innerWidth, window.innerHeight, false);
    dustUniforms.uPointScale.value = window.innerHeight * Math.min(window.devicePixelRatio || 1, 2) / (2 * Math.tan(THREE.MathUtils.degToRad(35 / 2)));
    renderer.render(scene, camera);
  }

  // An in-memory lightbox is baked into a filtered environment for specular glass and metal.
  const studio = new THREE.Scene();
  studio.background = new THREE.Color(0x111820);
  function panel(color, intensity, x, y, z, width, height) {
    const mat = new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(intensity), side: THREE.DoubleSide });
    const m = new THREE.Mesh(new THREE.PlaneGeometry(width, height), mat);
    m.position.set(x, y, z);
    m.lookAt(0, 0, 0);
    studio.add(m);
  }
  panel(0xf3fbff, 3.3, -4, 3, 4, 2.0, 6.5);
  panel(0xd5f5ff, 2.4, 4, 1, 2.5, 1.0, 6.5);
  panel(0x74dff2, 2.1, -4, 0, -2.0, 0.7, 6.0);
  panel(0xe891dc, 1.4, 4, -0.2, -3, 1.1, 5.0);
  panel(0xffffff, 2.6, 0, 5, 1, 4.0, 1.3);
  const pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileCubemapShader();
  const environment = pmrem.fromScene(studio, 0.04).texture;
  scene.environment = environment;
  pmrem.dispose();

  scene.add(new THREE.HemisphereLight(0xcce8f3, 0x15212b, 0.65));
  const key = new THREE.DirectionalLight(0xf5fbff, 1.7);
  key.position.set(-3.5, 5, 6);
  scene.add(key);
  const cyan = new THREE.DirectionalLight(0x7ad8f4, 1.35);
  cyan.position.set(-4, 1, -3);
  scene.add(cyan);
  const magenta = new THREE.DirectionalLight(0xf49be7, 0.9);
  magenta.position.set(4, 2, -2);
  scene.add(magenta);
  const fill = new THREE.DirectionalLight(0xb0d6e9, 0.65);
  fill.position.set(3, -3, 5);
  scene.add(fill);

  // The profile is a quenched bulb, a long taper and a small helical curl.
  const profile = [
    [0, 0.018], [0.018, 0.26], [0.05, 0.48], [0.09, 0.65],
    [0.14, 0.735], [0.19, 0.73], [0.24, 0.65], [0.30, 0.51],
    [0.38, 0.33], [0.48, 0.17], [0.58, 0.105], [0.72, 0.065],
    [0.86, 0.043], [1, 0.021]
  ];
  function radiusAt(s) {
    s = clamp(s, 0, 1);
    let i = 0;
    while (i < profile.length - 2 && s > profile[i + 1][0]) i++;
    const p0 = profile[Math.max(0, i - 1)];
    const p1 = profile[i];
    const p2 = profile[i + 1];
    const p3 = profile[Math.min(profile.length - 1, i + 2)];
    const d = p2[0] - p1[0];
    const u = (s - p1[0]) / d;
    const m1 = (p2[1] - p0[1]) / (p2[0] - p0[0]);
    const m2 = (p3[1] - p1[1]) / (p3[0] - p1[0]);
    const u2 = u * u, u3 = u2 * u;
    return Math.max(0.014, (2*u3-3*u2+1)*p1[1] + (u3-2*u2+u)*d*m1 + (-2*u3+3*u2)*p2[1] + (u3-u2)*d*m2);
  }
  function spine(s) {
    const v = clamp((s - 0.76) / 0.24, 0, 1);
    return new THREE.Vector3(-0.3 + 0.6*s + 0.10*Math.sin(s*5) + 0.15*Math.sin(v*Math.PI*2),
      -2.2 + 4.65*s, 0.12*(Math.cos(v*Math.PI*2)-1));
  }
  function frameAt(s) {
    const p = spine(s);
    const tangent = spine(Math.min(1, s + 0.0005)).sub(spine(Math.max(0, s - 0.0005))).normalize();
    const normal = new THREE.Vector3(tangent.y, -tangent.x, 0).normalize();
    const binormal = new THREE.Vector3().crossVectors(tangent, normal).normalize();
    return { p, tangent, normal, binormal };
  }
  function pointInDrop(s, angle, r) {
    const f = frameAt(s);
    return f.p.addScaledVector(f.normal, Math.cos(angle) * r).addScaledVector(f.binormal, Math.sin(angle) * r);
  }
  function makeDropGeometry() {
    const lengthSegments = 180, radialSegments = 48;
    const positions = [], spineValues = [], angles = [], indices = [];
    for (let i = 0; i <= lengthSegments; i++) {
      const s = i / lengthSegments;
      const f = frameAt(s), radius = radiusAt(s);
      for (let j = 0; j <= radialSegments; j++) {
        const a = j / radialSegments * Math.PI * 2;
        const p = f.p.clone().addScaledVector(f.normal, Math.cos(a)*radius).addScaledVector(f.binormal, Math.sin(a)*radius);
        positions.push(p.x, p.y, p.z);
        spineValues.push(s);
        angles.push(a);
      }
    }
    for (let i = 0; i < lengthSegments; i++) {
      for (let j = 0; j < radialSegments; j++) {
        const a = i*(radialSegments+1)+j, b = a+1, c = a+radialSegments+1, d = c+1;
        indices.push(a, b, c, b, d, c);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setIndex(indices);
    g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    g.setAttribute('aSpine', new THREE.Float32BufferAttribute(spineValues, 1));
    g.setAttribute('aAngle', new THREE.Float32BufferAttribute(angles, 1));
    g.computeVertexNormals();
    return g;
  }
  const dropGeometry = makeDropGeometry();
  const timeUniform = { value: 0 };
  const frontUniform = { value: 1.01 };
  const cutUniform = { value: 0 };
  const glass = new THREE.MeshPhysicalMaterial({
    color: 0xb6e3ea, metalness: 0.02, roughness: 0.065,
    transmission: 0.91, thickness: 0.7, ior: 1.48,
    clearcoat: 1, clearcoatRoughness: 0.045, envMapIntensity: 1.4
  });
  glass.onBeforeCompile = shader => {
    shader.uniforms.uFront = frontUniform;
    shader.uniforms.uCut = cutUniform;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\\nattribute float aSpine; varying float vSpine;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\\nvSpine = aSpine;');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\\nuniform float uFront; uniform float uCut; varying float vSpine;')
      .replace('#include <clipping_planes_fragment>', '#include <clipping_planes_fragment>\\nif (vSpine > uFront || (uCut > 0.5 && vSpine > 0.988)) discard;');
  };
  const dropGroup = new THREE.Group();
  scene.add(dropGroup);
  dropGroup.add(new THREE.Mesh(dropGeometry, glass));

  // A second, thin optical layer adds Fresnel edges and cross-polarized stress fringes.
  const stress = new THREE.ShaderMaterial({
    uniforms: { uTime: timeUniform, uFront: frontUniform, uCut: cutUniform },
    transparent: true, depthWrite: false, side: THREE.FrontSide,
    vertexShader: "'`
      attribute float aSpine;
      attribute float aAngle;
      varying float vSpine;
      varying float vAngle;
      varying vec3 vNormalView;
      varying vec3 vToEye;
      void main() {
        vSpine = aSpine;
        vAngle = aAngle;
        vNormalView = normalize(normalMatrix * normal);
        vec4 mv = modelViewMatrix * vec4(position + normal * 0.004, 1.0);
        vToEye = -mv.xyz;
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform float uFront;
      uniform float uCut;
      varying float vSpine;
      varying float vAngle;
      varying vec3 vNormalView;
      varying vec3 vToEye;
      void main() {
        if (vSpine > uFront || (uCut > 0.5 && vSpine > 0.988)) discard;
        float facing = abs(dot(normalize(vNormalView), normalize(vToEye)));
        float rim = pow(1.0 - facing, 2.2);
        float body = 1.0 - smoothstep(0.36, 0.58, vSpine);
        float pulse = exp(-abs(uTime - 3.15)*2.2) * 0.45;
        float phase = vSpine * 44.0 + 4.0*cos(vAngle) + pulse * sin(vSpine*18.0);
        float bands = pow(0.5 + 0.5*cos(phase), 4.0) * body;
        vec3 spectral = 0.5 + 0.5*cos(vec3(0.0, 2.1, 4.2) + phase*0.30 + 0.8);
        vec3 c = vec3(0.23, 0.57, 0.64) * (0.38 + 1.5*rim) + spectral * bands * (0.14 + pulse*0.12);
        float alpha = clamp(0.035 + 0.36*rim + bands*0.10, 0.0, 0.65);
        gl_FragColor = vec4(c, alpha);
      }
    `
  });
  const opticalShell = new THREE.Mesh(dropGeometry, stress);
  opticalShell.renderOrder = 3;
  dropGroup.add(opticalShell);

  // A fine hanging wire is deliberately kept behind the glass and tools.
  const tip = spine(1);
  const wireCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(tip.x, tip.y, -0.20),
    new THREE.Vector3(tip.x-0.05, 3.20, -0.22),
    new THREE.Vector3(tip.x-0.08, 4.7, -0.24)
  ]);
  const wire = new THREE.Mesh(new THREE.TubeGeometry(wireCurve, 32, 0.007, 5, false),
    new THREE.MeshStandardMaterial({color:0x788d98, metalness:0.9, roughness:0.33}));
  scene.add(wire);

  // Projectile: the local X axis points from the rear toward the impact face.
  const bulletProfile = [
    new THREE.Vector2(0, -0.47), new THREE.Vector2(0.215, -0.47),
    new THREE.Vector2(0.235, -0.42), new THREE.Vector2(0.235, 0.12),
    new THREE.Vector2(0.225, 0.23), new THREE.Vector2(0.19, 0.34),
    new THREE.Vector2(0.12, 0.43), new THREE.Vector2(0, 0.49)
  ];
  const bulletGeometry = new THREE.LatheGeometry(bulletProfile, 48);
  bulletGeometry.rotateZ(Math.PI / 2);
  const bulletMaterial = new THREE.MeshPhysicalMaterial({color:0x939ca0, metalness:0.97, roughness:0.22, clearcoat:0.35, transparent:true});
  const copperMaterial = new THREE.MeshStandardMaterial({color:0x9c6c55, metalness:0.92, roughness:0.26, transparent:true});
  const bullet = new THREE.Group();
  bullet.add(new THREE.Mesh(bulletGeometry, bulletMaterial));
  for (const x of [0.31, 0.39]) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.237, 0.012, 8, 40), copperMaterial);
    ring.rotation.y = Math.PI / 2;
    ring.position.x = x;
    bullet.add(ring);
  }
  scene.add(bullet);
  const impactX = 0.60, impactY = -1.50;

  // Compact, articulated steel nippers. Both arms rotate about the same rivet.
  const steel = new THREE.MeshPhysicalMaterial({color:0x8c9aa3, metalness:0.92, roughness:0.24, clearcoat:0.32});
  const darkSteel = new THREE.MeshStandardMaterial({color:0x26343c, metalness:0.82, roughness:0.3});
  const gripMaterial = new THREE.MeshStandardMaterial({color:0x27343b, metalness:0.7, roughness:0.35});
  const jawShape = new THREE.Shape();
  jawShape.moveTo(-1.03, -0.035);
  jawShape.lineTo(-0.97, 0.035);
  jawShape.lineTo(-0.60, 0.105);
  jawShape.lineTo(-0.15, 0.15);
  jawShape.lineTo(0.25, 0.13);
  jawShape.lineTo(1.14, 0.11);
  jawShape.lineTo(1.25, 0.065);
  jawShape.lineTo(1.25, -0.065);
  jawShape.lineTo(1.14, -0.11);
  jawShape.lineTo(0.25, -0.10);
  jawShape.lineTo(-0.15, -0.12);
  jawShape.lineTo(-0.60, -0.065);
  jawShape.closePath();
  const jawGeometry = new THREE.ExtrudeGeometry(jawShape, {depth:0.10, bevelEnabled:true, bevelSize:0.035, bevelThickness:0.025, bevelSegments:2, steps:1});
  jawGeometry.translate(0, 0, -0.05);
  const nippers = new THREE.Group();
  nippers.position.set(1.25, tip.y, 0.18);
  scene.add(nippers);
  function makeArm(z) {
    const arm = new THREE.Group();
    arm.position.z = z;
    arm.add(new THREE.Mesh(jawGeometry, steel));
    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.205, 0.15), gripMaterial);
    grip.position.set(0.82, 0, 0);
    arm.add(grip);
    const inlay = new THREE.Mesh(new THREE.BoxGeometry(0.49, 0.018, 0.015), steel);
    inlay.position.set(0.82, 0.04, 0.081);
    arm.add(inlay);
    nippers.add(arm);
    return arm;
  }
  const upperArm = makeArm(0.08), lowerArm = makeArm(-0.08);
  const rivet = new THREE.Mesh(new THREE.CylinderGeometry(0.145, 0.145, 0.25, 32), steel);
  rivet.rotation.x = Math.PI / 2;
  rivet.position.z = 0.04;
  nippers.add(rivet);
  const rivetCap = new THREE.Mesh(new THREE.CylinderGeometry(0.073, 0.073, 0.012, 32), darkSteel);
  rivetCap.rotation.x = Math.PI / 2;
  rivetCap.position.z = 0.174;
  nippers.add(rivetCap);

  // A detached canvas supplies the glow texture, with no network or DOM attachment.
  const glowCanvas = document.createElement('"'canvas');
  glowCanvas.width = glowCanvas.height = 128;
  const glowContext = glowCanvas.getContext('2d');
  const glowGradient = glowContext.createRadialGradient(64, 64, 0, 64, 64, 64);
  glowGradient.addColorStop(0, 'rgba(255,255,255,1)');
  glowGradient.addColorStop(0.12, 'rgba(220,248,255,0.9)');
  glowGradient.addColorStop(0.38, 'rgba(100,203,255,0.22)');
  glowGradient.addColorStop(1, 'rgba(70,160,255,0)');
  glowContext.fillStyle = glowGradient;
  glowContext.fillRect(0, 0, 128, 128);
  const glowTexture = new THREE.CanvasTexture(glowCanvas);
  function makeGlow() {
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({map:glowTexture, color:0xc6f3ff, transparent:true, depthWrite:false, blending:THREE.AdditiveBlending}));
    scene.add(sprite);
    return sprite;
  }
  const snipGlow = makeGlow();
  const frontGlow = makeGlow();
  const shockRing = new THREE.Mesh(new THREE.RingGeometry(0.19, 0.205, 64),
    new THREE.MeshBasicMaterial({color:0xc9f2ff, transparent:true, opacity:0, depthWrite:false, side:THREE.DoubleSide, blending:THREE.AdditiveBlending}));
  shockRing.position.set(impactX-0.12, impactY, 0.77);
  scene.add(shockRing);
  const frontCap = new THREE.Mesh(new THREE.SphereGeometry(1, 28, 14),
    new THREE.MeshBasicMaterial({color:0xe9fbff, transparent:true, opacity:0.9, depthWrite:false}));
  scene.add(frontCap);

  // Each crystal and each metal fragment receives a fixed origin, birth time and velocity.
  // Their ballistic position and rotation are evaluated in the vertex shader at uTime.
  function particleMaterial(color, fade) {
    const material = new THREE.MeshStandardMaterial({color, metalness:0.63, roughness:0.19, flatShading:true, envMapIntensity:1.6});
    material.onBeforeCompile = shader => {
      shader.uniforms.uTime = timeUniform;
      shader.vertexShader = shader.vertexShader.replace('#include <common>', "'`
        #include <common>
        attribute vec3 aVelocity;
        attribute float aBirth;
        attribute vec4 aSpin;
        uniform float uTime;
        vec3 particleRotate(vec3 p, vec3 axis, float angle) {
          float c = cos(angle), s = sin(angle);
          return p*c + cross(axis, p)*s + axis*dot(axis,p)*(1.0-c);
        }
      `).replace('"'#include <beginnormal_vertex>', "'`
        float particleAge = max(0.0, uTime - aBirth);
        vec3 objectNormal = particleRotate(normal, aSpin.xyz, particleAge*aSpin.w);
        #ifdef USE_TANGENT
          vec3 objectTangent = particleRotate(tangent.xyz, aSpin.xyz, particleAge*aSpin.w);
        #endif
      `).replace('"'#include <begin_vertex>', "'`
        float particleLive = step(aBirth, uTime) * smoothstep(0.0, 0.085, particleAge);
        ${fade ? '"'particleLive *= 1.0 - smoothstep(1.0, 1.75, particleAge);' : ''}
